### BRFSS & YRBS SO Analyses - 18 YO formal comparisons

# This script's code uses the SO analytic objects generated by "SOGI_04_SO prepare"
### and produces statistical comparisons and corresponding graphs of 18 YOs in either survey

### Prepare workspace ----- 
# clear environment
rm(list = ls())

# packages
source("SOGI_00_packages.R")

# define functions
tableNA <- function(x, ...){
   table(x, useNA = "ifany", ...)  
}

# call in data
brfss_dat <- readRDS("data - clean/brfss_final.rds")
yrbs_dat <- readRDS("data - clean/yrbs_final.rds")
combined <- readRDS("data - clean/combined.rds")
so_props_A <- readRDS("data - clean/so_props_A.rds")
so_props_F <- readRDS("data - clean/so_props_F.rds")
so_props_M <- readRDS("data - clean/so_props_M.rds")

# generate binary SO variables for 18-yo comparison
combined_18 <- subset(combined, age == 18)
brfss_dat_18 <- subset(brfss_dat, age == 18)
yrbs_dat_18 <- subset(yrbs_dat, age == 18)

combined_18$str01 <- ifelse(combined_18$so_new == "1_straight", 1, 0)
combined_18$lg01 <- ifelse(combined_18$so_new == "2_lesgay", 1, 0)
combined_18$bi01 <- ifelse(combined_18$so_new == "3_bi", 1, 0)
combined_18$dko01 <- ifelse(combined_18$so_new == "4_dko", 1, 0)
combined_18$ref01 <- ifelse(combined_18$so_new == "5_ref", 1, 0)

brfss_dat_18$str01 <- ifelse(brfss_dat_18$so_new == "1_straight", 1, 0)
brfss_dat_18$lg01 <- ifelse(brfss_dat_18$so_new == "2_lesgay", 1, 0)
brfss_dat_18$bi01 <- ifelse(brfss_dat_18$so_new == "3_bi", 1, 0)
brfss_dat_18$dko01 <- ifelse(brfss_dat_18$so_new == "4_dko", 1, 0)
brfss_dat_18$ref01 <- ifelse(brfss_dat_18$so_new == "5_ref", 1, 0)
brfss_dat_18$pid <- seq(1, nrow(brfss_dat_18))

yrbs_dat_18$str01 <- ifelse(yrbs_dat_18$so_new == "1_straight", 1, 0)
yrbs_dat_18$lg01 <- ifelse(yrbs_dat_18$so_new == "2_lesgay", 1, 0)
yrbs_dat_18$bi01 <- ifelse(yrbs_dat_18$so_new == "3_bi", 1, 0)
yrbs_dat_18$dko01 <- ifelse(yrbs_dat_18$so_new == "4_dko", 1, 0)
yrbs_dat_18$ref01 <- ifelse(yrbs_dat_18$so_new == "5_ref", 1, 0)
yrbs_dat_18$pid <- seq(1, nrow(yrbs_dat_18))

# * Statistical Tests (no sex stratification) -----
combined_15 <- subset(combined_18, year == 2015)
combined_17 <- subset(combined_18, year == 2017)
combined_19 <- subset(combined_18, year == 2019)
combined_21 <- subset(combined_18, year == 2021)

brfss_dat_15 <- subset(brfss_dat_18, year == 2015)
brfss_dat_17 <- subset(brfss_dat_18, year == 2017)
brfss_dat_19 <- subset(brfss_dat_18, year == 2019)
brfss_dat_21 <- subset(brfss_dat_18, year == 2021)

yrbs_dat_15 <- subset(yrbs_dat_18, year == 2015)
yrbs_dat_17 <- subset(yrbs_dat_18, year == 2017)
yrbs_dat_19 <- subset(yrbs_dat_18, year == 2019)
yrbs_dat_21 <- subset(yrbs_dat_18, year == 2021)

# formal statistical comparisons

# * 2015
wtd.chi.sq(combined_15$source,
           combined_15$str01,
           weight = combined_15$weight) # p = 0.7

wtd.chi.sq(combined_15$source,
           combined_15$lg01,
           weight = combined_15$weight) # p = 0.1

wtd.chi.sq(combined_15$source,
           combined_15$bi01,
           weight = combined_15$weight) # p = 0.01 ***

wtd.chi.sq(combined_15$source,
           combined_15$dko01,
           weight = combined_15$weight) # p = 0.0000002 ***

wtd.chi.sq(combined_15$source,
           combined_15$ref01,
           weight = combined_15$weight) # p = 0.005 ***


# * 2017
wtd.chi.sq(combined_17$source,
           combined_17$str01,
           weight = combined_17$weight) # p = 0.8

wtd.chi.sq(combined_17$source,
           combined_17$lg01,
           weight = combined_17$weight) # p = 0.4

wtd.chi.sq(combined_17$source,
           combined_17$bi01,
           weight = combined_17$weight) # p = 0.2

wtd.chi.sq(combined_17$source,
           combined_17$dko01,
           weight = combined_17$weight) # p = 0.00001 ***

wtd.chi.sq(combined_17$source,
           combined_17$ref01,
           weight = combined_17$weight) # p = 0.01 ***

# * 2019
wtd.chi.sq(combined_19$source,
           combined_19$str01,
           weight = combined_19$weight) # = 0.01 ***

wtd.chi.sq(combined_19$source,
           combined_19$lg01,
           weight = combined_19$weight) # p = 0.999

wtd.chi.sq(combined_19$source,
           combined_19$bi01,
           weight = combined_19$weight) # p = 0.0006 ***

wtd.chi.sq(combined_19$source,
           combined_19$dko01,
           weight = combined_19$weight) # p = 0.9

wtd.chi.sq(combined_19$source,
           combined_19$ref01,
           weight = combined_19$weight) # p = 0.3


# * 2021
wtd.chi.sq(combined_21$source,
           combined_21$str01,
           weight = combined_21$weight) # p = 0.5

wtd.chi.sq(combined_21$source,
           combined_21$lg01,
           weight = combined_21$weight) # p = 0.75

wtd.chi.sq(combined_21$source,
           combined_21$bi01,
           weight = combined_21$weight) # p = 0.9

wtd.chi.sq(combined_21$source,
           combined_21$dko01,
           weight = combined_21$weight) # p =0.6

wtd.chi.sq(combined_21$source,
           combined_21$ref01,
           weight = combined_21$weight) # p = 0.3

# * Plot the estimated % and 95% CI for each SO, each year, by data source ------
#generate object with survey weights info
# BRFSS
brfss_des_15 <- svydesign(id=~pid, weights=~weight, data = brfss_dat_15)
brfss_des_17 <- svydesign(id=~pid, weights=~weight, data = brfss_dat_17)
brfss_des_19 <- svydesign(id=~pid, weights=~weight, data = brfss_dat_19)
